const planets = {
  luma: {
    id: 'luma',
    homeX: 4.2,
    homeY: 4.5,
    closeX: 5.8,
    closeY: 5.2,
    x: 4.2,
    y: 4.5,
    startX: 4.2,
    startY: 4.5,
    targetX: 4.2,
    targetY: 4.5,
    isClose: false,
    moving: false,
    elapsed: 0,
    duration: 1.6
  },
  rumi: {
    id: 'rumi',
    homeX: 11.8,
    homeY: 4.5,
    closeX: 10.2,
    closeY: 5.2,
    x: 11.8,
    y: 4.5,
    startX: 11.8,
    startY: 4.5,
    targetX: 11.8,
    targetY: 4.5,
    isClose: false,
    moving: false,
    elapsed: 0,
    duration: 1.6
  }
};

game.setGravity(0);

function getPlanetEntity(id) {
  const found = game.find(id);
  return found.length > 0 ? found[0] : null;
}

function togglePlanetGlide(planet) {
  const ent = getPlanetEntity(planet.id);
  if (ent) {
    planet.x = ent.x;
    planet.y = ent.y;
  }
  planet.isClose = !planet.isClose;
  planet.startX = planet.x;
  planet.startY = planet.y;
  planet.targetX = planet.isClose ? planet.closeX : planet.homeX;
  planet.targetY = planet.isClose ? planet.closeY : planet.homeY;
  planet.elapsed = 0;
  planet.moving = true;
  game.sound('whoosh');
}

game.on('tap', (e) => {
  if (!e.target) return;
  if (e.target.id === 'luma' || e.target.tags.includes('luma')) {
    togglePlanetGlide(planets.luma);
  } else if (e.target.id === 'rumi' || e.target.tags.includes('rumi')) {
    togglePlanetGlide(planets.rumi);
  }
});

game.on('tick', (e) => {
  const dt = e.dt > 0 ? e.dt : 0.05;
  const keys = ['luma', 'rumi'];
  for (let i = 0; i < keys.length; i++) {
    const p = planets[keys[i]];
    const ent = getPlanetEntity(p.id);
    if (!ent) continue;

    if (p.moving) {
      p.elapsed += dt;
      const t = Math.min(1, p.elapsed / p.duration);
      const s = t * t * (3 - 2 * t);
      const nextX = p.startX + (p.targetX - p.startX) * s;
      const nextY = p.startY + (p.targetY - p.startY) * s;
      const desiredVx = t < 1 ? (nextX - p.x) / dt : 0;
      const desiredVy = t < 1 ? (nextY - p.y) / dt : 0;

      p.x = nextX;
      p.y = nextY;
      game.move(p.id, { x: p.x, y: p.y });
      game.impulse(p.id, { x: desiredVx - ent.vx, y: desiredVy - ent.vy });

      if (t >= 1) {
        p.moving = false;
        p.x = p.targetX;
        p.y = p.targetY;
        game.move(p.id, { x: p.targetX, y: p.targetY });
        game.impulse(p.id, { x: -ent.vx, y: -ent.vy });
        if (p.isClose) {
          game.sound('ding');
          game.celebrate('sparkle');
        } else {
          game.sound('pop');
        }
      }
    } else {
      const dx = p.targetX - ent.x;
      const dy = p.targetY - ent.y;
      if (Math.abs(dx) > 0.01 || Math.abs(dy) > 0.01) {
        game.move(p.id, { x: p.targetX, y: p.targetY });
      }
      if (Math.abs(ent.vx) > 0.01 || Math.abs(ent.vy) > 0.01) {
        game.impulse(p.id, { x: -ent.vx, y: -ent.vy });
      }
    }
  }
});
